using System.Net.Http.Json; using System.Text.Json;
namespace Library.Admin.WinForms;
public class MainForm:Form {
 readonly HttpClient api=new(){BaseAddress=new Uri("http://localhost:5001/")}; readonly TextBox search=new(){Width=280,PlaceholderText="Tên sách / ISBN"}; readonly DataGridView grid=new(){Dock=DockStyle.Fill,ReadOnly=true,AutoGenerateColumns=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill}; readonly Label status=new(){AutoSize=true,Text="Sẵn sàng"};
 public MainForm(){Text="Quản lý thư viện · Thủ thư";Width=1050;Height=680;StartPosition=FormStartPosition.CenterScreen;var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=54,Padding=new Padding(12)};var btn=new Button{Text="Tra cứu",AutoSize=true};btn.Click+=async(_,_)=>await Search();top.Controls.AddRange([new Label{Text="Danh mục sách",AutoSize=true,Padding=new Padding(0,8,12,0)},search,btn,status]);Controls.Add(grid);Controls.Add(top);Load+=async(_,_)=>await Search();}
 async Task Search(){try{status.Text="Đang tải...";var q=Uri.EscapeDataString(search.Text.Trim());var rows=await api.GetFromJsonAsync<JsonElement[]>($"api/catalog/books?q={q}");grid.DataSource=rows?.Select(x=>new {Mã=x.GetProperty("id").GetInt32(),Tên=x.GetProperty("title").GetString(),ISBN=x.GetProperty("isbn").ToString(),Có_sẵn=x.GetProperty("available").GetInt32()}).ToList();status.Text=$"Đã tải {grid.Rows.Count} dòng";}catch(Exception ex){status.Text="Không kết nối API";MessageBox.Show("Hãy chạy API và kiểm tra kết nối SQL Server.\n"+ex.Message,"Lỗi kết nối",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
}
